// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint96 amount) public {
        uint potBefore = c.pot();
        vm.deal(address(this), amount);
        if (amount >= 10) {
            // Drive the call
            c.play{value: 10}();
            // After play, pot should be potBefore + 10 (since the win condition doesn't affect pot addition)
            assertTrue(c.pot() == potBefore + 10 || c.pot() == 0);
        } else {
            vm.expectRevert();
            c.play{value: amount}();
            assertTrue(c.pot() == potBefore);
        }
    }
}

